">Author biography <span>used only when Author role is assigned</span></label><textarea class="portal-textarea" id="biography" name="biography" rows="4">{{ old('biography',$profile?->biography) }}</textarea></div></div>
<fieldset class="portal-field"><legend>Roles</legend><div class="choice-grid">@foreach($roles as $role)@if($role->slug!=='super-admin'||auth()->user()->hasRole('super-admin'))<label class="choice-card"><input type="checkbox" name="roles[]" value="{{ $role->id }}" @checked(in_array($role->id,$selectedRoles))> <strong>{{ $role->name }}</strong><small style="display:block;color:var(--portal-muted)">{{ $role->description }}</small></label>@endif @endforeach</div><x-portal.field-error name="roles" /></fieldset>
